89	func (s *Store) CreateAttachment(ctx context.Context, create *Attachment) (*Attachment, error) {
90		if !base.UIDMatcher.MatchString(create.UID) {
91			return nil, errors.New("invalid uid")
92		}
93		return s.driver.CreateAttachment(ctx, create)
94	}
95	
96	func (s *Store) ListAttachments(ctx context.Context, find *FindAttachment) ([]*Attachment, error) {
97		// Set default limits to prevent loading too many attachments at once
98		shouldApplyDefaultLimit := find.Limit == nil && len(find.MemoIDList) == 0
99		if shouldApplyDefaultLimit && find.GetBlob {
100			// When fetching blobs, we should be especially careful with limits
101			defaultLimit := 10
102			find.Limit = &defaultLimit
103		} else if shouldApplyDefaultLimit {
104			// Even without blobs, let's default to a reasonable limit
105			defaultLimit := 100
106			find.Limit = &defaultLimit
107		}
108	
109		return s.driver.ListAttachments(ctx, find)
110	}
111	
112	func (s *Store) GetAttachment(ctx context.Context, find *FindAttachment) (*Attachment, error) {
113		attachments, err := s.ListAttachments(ctx, find)
114		if err != nil {
115			return nil, err
116		}
117	
118		if len(attachments) == 0 {
119			return nil, nil
120		}
121	
122		return attachments[0], nil
123	}
124	
125	func (s *Store) UpdateAttachment(ctx context.Context, update *UpdateAttachment) error {
126		if update.UID != nil && !base.UIDMatcher.MatchString(*update.UID) {
127			return errors.New("invalid uid")
128		}
129		return s.driver.UpdateAttachment(ctx, update)
130	}
131	
132	func (s *Store) DeleteAttachment(ctx context.Context, delete *DeleteAttachment) error {
133		attachment, err := s.GetAttachment(ctx, &FindAttachment{ID: &delete.ID})
134		if err != nil {
135			return errors.Wrap(err, "failed to get attachment")
136		}
137		if attachment == nil {
138			return errors.New("attachment not found")
139		}
140	
141		if err := s.DeleteAttachmentStorage(ctx, attachment); err != nil {
142			if attachment.StorageType == storepb.AttachmentStorageType_LOCAL {
143				return errors.Wrap(err, "failed to delete local file")
144			}
145			slog.Warn("Failed to delete attachment storage", slog.Any("err", err))
146		}
147	
148		return s.driver.DeleteAttachment(ctx, delete)
149	}
150	
151	func (s *Store) DeleteAttachments(ctx context.Context, attachments []*Attachment) error {
152		if len(attachments) == 0 {
153			return nil
154		}
155	
156		deletes := make([]*DeleteAttachment, 0, len(attachments))
157		for _, attachment := range attachments {
158			if attachment == nil {
159				continue
160			}
161			deletes = append(deletes, &DeleteAttachment{ID: attachment.ID, MemoID: attachment.MemoID})
162		}
163		if len(deletes) == 0 {
164			return nil
165		}
166	
167		if err := s.driver.DeleteAttachments(ctx, deletes); err != nil {
168			return err
169		}
170	
171		instanceStorageSetting, instanceStorageSettingErr := s.getAttachmentStorageCleanupInstanceSetting(ctx, attachments)
172		for _, attachment := range attachments {
173			if attachment == nil {
174				continue
175			}
176			var err error
177			if instanceStorageSettingErr != nil && AttachmentNeedsInstanceStorageSetting(attachment) {
178				err = instanceStorageSettingErr
179			} else {
180				err = s.deleteAttachmentStorageImpl(ctx, attachment, instanceStorageSetting)
181			}
182			if err != nil {
183				if attachment.StorageType == storepb.AttachmentStorageType_LOCAL {
184					return errors.Wrap(err, "failed to delete local file")
185				}
186				slog.Warn("Failed to delete attachment storage", slog.Any("err", err))
187			}
188		}
189	
190		return nil
191	}
192	
193	func (s *Store) DeleteAttachmentStorage(ctx context.Context, attachment *Attachment) error {
194		return s.deleteAttachmentStorageImpl(ctx, attachment, nil)
195	}
196	
197	// DeleteAttachmentStorageWithInstanceSetting deletes attachment storage using a preloaded instance storage setting.
198	func (s *Store) DeleteAttachmentStorageWithInstanceSetting(ctx context.Context, attachment *Attachment, instanceStorageSetting *storepb.InstanceStorageSetting) error {
199		return s.deleteAttachmentStorageImpl(ctx, attachment, instanceStorageSetting)
200	}
201	
202	func (s *Store) deleteAttachmentStorageImpl(ctx context.Context, attachment *Attachment, instanceStorageSetting *storepb.InstanceStorageSetting) error {
203		if attachment == nil {
204			return nil
205		}
206		if shouldFailDeleteAttachmentStorage(ctx) {
207			return ErrDeleteAttachmentStorageFailpoint
208		}
209	
210		if attachment.StorageType == storepb.AttachmentStorageType_LOCAL {
211			if err := func() error {
212				p := filepath.FromSlash(attachment.Reference)
213				if !filepath.IsAbs(p) {
214					p = filepath.Join(s.profile.Data, p)
215				}
216				err := os.Remove(p)
217				if err != nil && !os.IsNotExist(err) {
218					return errors.Wrap(err, "failed to delete local file")
219				}
220				return nil
221			}(); err != nil {
222				return err
223			}
224		} else if attachment.StorageType == storepb.AttachmentStorageType_S3 {
225			if err := func() error {
226				s3ObjectPayload := attachment.Payload.GetS3Object()
227				if s3ObjectPayload == nil {
228					return errors.Errorf("No s3 object found")
229				}
230				s3Config := s3ObjectPayload.S3Config
231				if s3Config == nil {
232					if instanceStorageSetting == nil {
233						var err error
234						instanceStorageSetting, err = s.GetInstanceStorageSetting(ctx)
235						if err != nil {
236							return errors.Wrap(err, "failed to get instance storage setting")
237						}
238					}
239					if instanceStorageSetting.S3Config == nil {
240						return errors.Errorf("S3 config is not found")
241					}
242					s3Config = instanceStorageSetting.S3Config
243				}
244	
245				s3Client, err := s3.NewClient(ctx, s3Config)
246				if err != nil {
247					return errors.Wrap(err, "Failed to create s3 client")
248				}
249				if err := s3Client.DeleteObject(ctx, s3ObjectPayload.Key); err != nil {
250					return errors.Wrap(err, "Failed to delete s3 object")
251				}
252				return nil
253			}(); err != nil {
254				return err
255			}
256		}
257	
258		s.deleteAttachmentDerivedCaches(attachment)
259		return nil
260	}
261	
262	func (s *Store) getAttachmentStorageCleanupInstanceSetting(ctx context.Context, attachments []*Attachment) (*storepb.InstanceStorageSetting, error) {
263		for _, attachment := range attachments {
264			if AttachmentNeedsInstanceStorageSetting(attachment) {
265				instanceStorageSetting, err := s.GetInstanceStorageSetting(ctx)
266				if err != nil {
267					return nil, errors.Wrap(err, "failed to get instance storage setting")
268				}
269				return instanceStorageSetting, nil
270			}
271		}
272		return nil, nil
273	}
274	
275	// AttachmentNeedsInstanceStorageSetting reports whether S3 cleanup needs the instance fallback storage setting.
276	func AttachmentNeedsInstanceStorageSetting(attachment *Attachment) bool {
277		if attachment == nil || attachment.StorageType != storepb.AttachmentStorageType_S3 {
278			return false
279		}
280		s3ObjectPayload := attachment.Payload.GetS3Object()
281		return s3ObjectPayload != nil && s3ObjectPayload.S3Config == nil
282	}
283	
284	func (s *Store) deleteAttachmentDerivedCaches(attachment *Attachment) {
285		for _, cachePath := range []string{
286			filepath.Join(s.profile.Data, thumbnailCacheFolder, attachment.UID+".jpeg"),
287			filepath.Join(s.profile.Data, motionCacheFolder, attachment.UID+".mp4"),
288		} {
289			if err := os.Remove(cachePath); err != nil && !os.IsNotExist(err) {
290				slog.Warn("Failed to delete derived attachment cache", slog.String("path", cachePath), slog.Any("err", err))
291			}
292		}
293	}
294	
295	func shouldFailDeleteAttachmentStorage(ctx context.Context) bool {
296		failpoint, ok := ctx.Value(deleteAttachmentStorageFailpointKey{}).(bool)
297		return ok && failpoint
298	}
