37	func (s *Store) CreateIdentityProvider(ctx context.Context, create *storepb.IdentityProvider) (*storepb.IdentityProvider, error) {
38		raw, err := convertIdentityProviderToRaw(create)
39		if err != nil {
40			return nil, err
41		}
42		identityProviderRaw, err := s.driver.CreateIdentityProvider(ctx, raw)
43		if err != nil {
44			return nil, err
45		}
46	
47		identityProvider, err := convertIdentityProviderFromRaw(identityProviderRaw)
48		if err != nil {
49			return nil, err
50		}
51		return identityProvider, nil
52	}
53	
54	func (s *Store) ListIdentityProviders(ctx context.Context, find *FindIdentityProvider) ([]*storepb.IdentityProvider, error) {
55		stored, err := s.listStoredIdentityProviders(ctx, find)
56		if err != nil {
57			return nil, err
58		}
59		// File-backed providers do not have database IDs. ID-filtered reads are raw
60		// stored-resource lookups used by mutation paths.
61		if find.ID != nil {
62			return stored, nil
63		}
64		if find.UID != nil {
65			if provider := s.getDeploymentIdentityProvider(*find.UID); provider != nil {
66				return []*storepb.IdentityProvider{provider}, nil
67			}
68			return stored, nil
69		}
70	
71		deploymentProviders := s.listDeploymentIdentityProviders()
72		deploymentByUID := make(map[string]*storepb.IdentityProvider, len(deploymentProviders))
73		for _, provider := range deploymentProviders {
74			deploymentByUID[provider.Uid] = provider
75		}
76		identityProviders := make([]*storepb.IdentityProvider, 0, len(stored)+len(deploymentProviders))
77		for _, provider := range stored {
78			if configured := deploymentByUID[provider.Uid]; configured != nil {
79				identityProviders = append(identityProviders, configured)
80				delete(deploymentByUID, provider.Uid)
81				continue
82			}
83			identityProviders = append(identityProviders, provider)
84		}
85		// listDeploymentIdentityProviders is UID-sorted, so providers that exist
86		// only in deployment configuration are appended deterministically without
87		// reordering existing database-backed providers.
88		for _, provider := range deploymentProviders {
89			if deploymentByUID[provider.Uid] != nil {
90				identityProviders = append(identityProviders, provider)
91			}
92		}
93		return identityProviders, nil
94	}
95	
96	func (s *Store) listStoredIdentityProviders(ctx context.Context, find *FindIdentityProvider) ([]*storepb.IdentityProvider, error) {
97		list, err := s.driver.ListIdentityProviders(ctx, find)
98		if err != nil {
99			return nil, err
100		}
101	
102		identityProviders := []*storepb.IdentityProvider{}
103		for _, raw := range list {
104			identityProvider, err := convertIdentityProviderFromRaw(raw)
105			if err != nil {
106				return nil, err
107			}
108			identityProviders = append(identityProviders, identityProvider)
109		}
110		return identityProviders, nil
111	}
112	
113	func (s *Store) GetIdentityProvider(ctx context.Context, find *FindIdentityProvider) (*storepb.IdentityProvider, error) {
114		list, err := s.ListIdentityProviders(ctx, find)
115		if err != nil {
116			return nil, err
117		}
118		if len(list) == 0 {
119			return nil, nil
120		}
121		if len(list) > 1 {
122			return nil, errors.New("found multiple identity providers")
123		}
124	
125		identityProvider := list[0]
126		return identityProvider, nil
127	}
