42	func (s *Store) UpsertUserSetting(ctx context.Context, upsert *storepb.UserSetting) (*storepb.UserSetting, error) {
43		userSettingRaw, err := convertUserSettingToRaw(upsert)
44		if err != nil {
45			return nil, err
46		}
47		userSettingRaw, err = s.driver.UpsertUserSetting(ctx, userSettingRaw)
48		if err != nil {
49			return nil, err
50		}
51	
52		userSetting, err := convertUserSettingFromRaw(userSettingRaw)
53		if err != nil {
54			return nil, err
55		}
56		if userSetting == nil {
57			return nil, errors.New("unexpected nil user setting")
58		}
59		s.userSettingCache.Set(ctx, getUserSettingCacheKey(userSetting.UserId, userSetting.Key.String()), userSetting)
60		return userSetting, nil
61	}
62	
63	func (s *Store) ListUserSettings(ctx context.Context, find *FindUserSetting) ([]*storepb.UserSetting, error) {
64		userSettingRawList, err := s.driver.ListUserSettings(ctx, find)
65		if err != nil {
66			return nil, err
67		}
68	
69		userSettings := []*storepb.UserSetting{}
70		for _, userSettingRaw := range userSettingRawList {
71			userSetting, err := convertUserSettingFromRaw(userSettingRaw)
72			if err != nil {
73				return nil, err
74			}
75			if userSetting == nil {
76				continue
77			}
78			s.userSettingCache.Set(ctx, getUserSettingCacheKey(userSetting.UserId, userSetting.Key.String()), userSetting)
79			userSettings = append(userSettings, userSetting)
80		}
81		return userSettings, nil
82	}
83	
84	func (s *Store) GetUserSetting(ctx context.Context, find *FindUserSetting) (*storepb.UserSetting, error) {
85		if find.UserID != nil {
86			if cache, ok := s.userSettingCache.Get(ctx, getUserSettingCacheKey(*find.UserID, find.Key.String())); ok {
87				userSetting, ok := cache.(*storepb.UserSetting)
88				if ok {
89					return userSetting, nil
90				}
91			}
92		}
93	
94		list, err := s.ListUserSettings(ctx, find)
95		if err != nil {
96			return nil, err
97		}
98		if len(list) == 0 {
99			return nil, nil
100		}
101		if len(list) > 1 {
102			return nil, errors.Errorf("expected 1 user setting, but got %d", len(list))
103		}
104	
105		userSetting := list[0]
